  2→ * Pure utility functions for field mapping normalization and initial value
  3→ * construction. Extracted from CriterionCard to keep the test import graph
  4→ * minimal (no React component dependencies).
  5→ */
  6→
  7→import type { Criterion } from '../hooks/useReviews';
  8→import { DEFAULT_FIELD_VALUES } from './structured-editor/constants';
  9→import type {
 10→    FieldMapping,
 11→    FieldValue,
 12→    RelationOperator,
 13→    StructuredFieldFormValues,
 14→    TemporalUnit,
 15→} from './structured-editor/types';
 16→
 17→export function formatTemporalConstraint(tc: Record<string, unknown>): string {
 18→    const duration = 'duration' in tc ? (tc.duration as string) : null;
 19→    const relation = 'relation' in tc ? (tc.relation as string) : null;
 20→    const referencePoint = 'reference_point' in tc ? (tc.reference_point as string) : null;
 21→
 22→    if (!duration) return '';
 23→
 24→    const relationMap: Record<string, string> = {
 25→        within: 'Within',
 26→        before: 'Before',
 27→        after: 'After',
 28→        at_least: 'At least',
 29→    };
 30→
 31→    const relationText = relation ? relationMap[relation] || relation : '';
 32→    const parts = [relationText, duration];
 33→    if (referencePoint) parts.push('of', referencePoint);
 34→
 35→    return parts.filter(Boolean).join(' ');
 36→}
 37→
 38→export function formatNumericThreshold(threshold: Record<string, unknown>): string {
 39→    const value = 'value' in threshold ? threshold.value : null;
 40→    const unit = 'unit' in threshold ? (threshold.unit as string) : '';
 41→    const comparator = 'comparator' in threshold ? (threshold.comparator as string) : '';
 42→    const upperValue = 'upper_value' in threshold ? threshold.upper_value : null;
 43→
 44→    if (value === null) return '';
 45→
 46→    if (comparator === 'range' && upperValue !== null) {
 47→        return `${value}-${upperValue} ${unit}`.trim();
 48→    }
 49→
 50→    return `${comparator}${value} ${unit}`.trim();
 51→}
 52→
 53→export function extractThresholdsList(
 54→    nt: Record<string, unknown> | null
 55→): Array<Record<string, unknown>> {
 56→    if (!nt) return [];
 57→
 58→    // Shape 1: {"thresholds": [...]} wrapper object
 59→    if ('thresholds' in nt && Array.isArray(nt.thresholds)) {
 60→        return nt.thresholds as Array<Record<string, unknown>>;
 61→    }
 62→
 63→    // Shape 2: raw array stored directly
 64→    if (Array.isArray(nt)) {
 65→        return nt as Array<Record<string, unknown>>;
 66→    }
 67→
 68→    // Shape 3: single threshold object without wrapper
 69→    if ('value' in nt && 'comparator' in nt) {
 70→        return [nt];
 71→    }
 72→
 73→    return [];
 74→}
 75→
 76→/** Map extraction comparator strings to RelationOperator. */
 77→function mapComparator(comparator: string): RelationOperator | '' {
 78→    const map: Record<string, RelationOperator> = {
 79→        '>=': '>=',
 80→        '<=': '<=',
 81→        '>': '>',
 82→        '<': '<',
 83→        '==': '=',
 84→        '=': '=',
 85→        range: 'within',
 86→    };
 87→    return map[comparator] ?? '';
 88→}
 89→
 90→/** Parse a duration string like "6 months" into {value, unit}. */
 91→function parseDuration(duration: string): {
 92→    value: string;
 93→    unit: TemporalUnit;
 94→} {
 95→    const match = duration.match(/^(\d+)\s*(days?|weeks?|months?|years?)$/i);
 96→    if (match) {
 97→        const raw = match[2].toLowerCase().replace(/s$/, '');
 98→        const unitMap: Record<string, TemporalUnit> = {
 99→            day: 'days',
100→            week: 'weeks',
101→            month: 'months',
102→            year: 'years',
103→        };
104→        return { value: match[1], unit: unitMap[raw] ?? 'days' };
105→    }
106→    return { value: duration, unit: 'days' };
107→}
108→
109→/** Valid frontend relation operators. */
110→const VALID_RELATIONS = new Set<string>([
111→    '=',
112→    '!=',
113→    '>',
114→    '>=',
115→    '<',
116→    '<=',
117→    'within',
118→    'not_in_last',
119→    'contains',
120→    'not_contains',
121→]);
122→
123→/** Normalize a raw relation string to a valid RelationOperator or empty. */
124→export function normalizeRelation(raw: string): RelationOperator | '' {
125→    const map: Record<string, RelationOperator> = {
126→        has: 'contains',
127→        is: '=',
128→        not: 'not_contains',
129→        '==': '=',
130→        range: 'within',
131→    };
132→    const mapped = map[raw] ?? raw;
133→    return VALID_RELATIONS.has(mapped) ? (mapped as RelationOperator) : '';
134→}
135→
136→/** Normalize a field mapping's value to a typed FieldValue. */
137→export function normalizeFieldValue(fm: Record<string, unknown>): FieldValue {
138→    const rawVal = fm.value;
139→
140→    // New typed format: value is an object with a 'type' key
141→    if (rawVal && typeof rawVal === 'object' && !Array.isArray(rawVal)) {
142→        const obj = rawVal as Record<string, unknown>;
143→        if (obj.type === 'range') {
144→            return {
145→                type: 'range',
146→                min: String(obj.min ?? ''),
147→                max: String(obj.max ?? ''),
148→                unit: String(obj.unit ?? ''),
149→            };
150→        }
151→        if (obj.type === 'temporal') {
152→            return {
153→                type: 'temporal',
154→                duration: String(obj.duration ?? ''),
155→                unit: (obj.unit as TemporalUnit) ?? 'days',
156→            };
157→        }
158→        if (obj.type === 'standard') {
159→            return {
160→                type: 'standard',
161→                value: String(obj.value ?? ''),
162→                unit: String(obj.unit ?? ''),
163→            };
164→        }
165→    }
166→
167→    // Legacy flat format: value is a string or number
168→    if (typeof rawVal === 'string' || typeof rawVal === 'number') {
169→        return {
170→            type: 'standard',
171→            value: String(rawVal),
172→            unit: String(fm.unit ?? ''),
173→        };
174→    }
175→
176→    return { type: 'standard', value: '', unit: '' };
177→}
178→
179→/**
180→ * Build initial form values for the structured editor from a criterion's
181→ * AI-extracted data (numeric_thresholds, temporal_constraint, conditions).
182→ */
183→export function buildInitialValues(criterion: Criterion): StructuredFieldFormValues {
184→    // Priority 1: existing field_mappings from a previous structured edit
185→    const cond = criterion.conditions as Record<string, unknown> | null;
186→    if (cond && 'field_mappings' in cond && Array.isArray(cond.field_mappings)) {
187→        const fms = cond.field_mappings as Array<Record<string, unknown>>;
188→        const mappings: FieldMapping[] = fms.map((fm) => {
189→            const rel = (fm.relation as string) ?? '';
190→            const value = normalizeFieldValue(fm);
191→            return {
192→                entity: String(fm.entity ?? ''),
193→                entity_code:
194→                    (fm.entity_code ?? fm.entity_concept_id)
195→                        ? String(fm.entity_code ?? fm.entity_concept_id)
196→                        : undefined,
197→                entity_system:
198→                    (fm.entity_system ?? fm.entity_concept_system)
199→                        ? String(fm.entity_system ?? fm.entity_concept_system)
200→                        : undefined,
201→                omop_concept_id: fm.omop_concept_id ? String(fm.omop_concept_id) : undefined,
202→                relation: normalizeRelation(rel),
203→                value,
204→            };
205→        });
206→        if (mappings.length > 0) return { mappings };
207→    }
208→
209→    // Priority 2: infer from AI-extracted data (entities + thresholds + temporal)
210→    const mappings: FieldMapping[] = [];
211→
212→    const entities = criterion.entities ?? [];
213→    const thresholds = extractThresholdsList(criterion.numeric_thresholds);
214→
215→    const entityLabel = (e: { preferred_term: string | null; text: string }) =>
216→        e.preferred_term || e.text;
217→
218→    const measurableEntities = entities.filter(
219→        (e) =>
220→            e.entity_type === 'Lab_Value' ||
221→            e.entity_type === 'Biomarker' ||
222→            e.entity_type === 'Demographic'
223→    );
224→
225→    const usedEntityIndices = new Set<number>();
226→
227→    for (let i = 0; i < thresholds.length; i++) {
228→        const t = thresholds[i];
229→        const comparator = (t.comparator as string) ?? '';
230→        const val = t.value as number | null;
231→        const unit = (t.unit as string) ?? '';
232→        const upperVal = t.upper_value as number | null;
233→
234→        if (val === null || val === undefined) continue;
235→
236→        // Find the next unused measurable entity
237→        let matchedEntity: (typeof measurableEntities)[number] | undefined;
238→        for (let j = 0; j < measurableEntities.length; j++) {
239→            if (!usedEntityIndices.has(j)) {
240→                matchedEntity = measurableEntities[j];
241→                usedEntityIndices.add(j);
242→                break;
243→            }
244→        }
245→        const entity = matchedEntity ? entityLabel(matchedEntity) : '';
246→        const entityCode = matchedEntity?.snomed_code ?? matchedEntity?.umls_cui ?? undefined;
247→        const entitySystem = matchedEntity?.snomed_code
248→            ? 'snomed'
249→            : matchedEntity?.umls_cui
250→              ? 'umls'
251→              : undefined;
252→
253→        if (comparator === 'range' && upperVal != null) {
254→            mappings.push({
255→                entity,
256→                entity_code: entityCode,
257→                entity_system: entitySystem,
258→                relation: 'within' as RelationOperator,
259→                value: { type: 'range', min: String(val), max: String(upperVal), unit },
260→            });
261→        } else {
262→            const relation = mapComparator(comparator);
263→            mappings.push({
264→                entity,
265→                entity_code: entityCode,
266→                entity_system: entitySystem,
267→                relation,
268→                value: { type: 'standard', value: String(val), unit },
269→            });
270→        }
271→    }
272→
273→    // Add remaining unmatched measurable entities with empty relation/value
274→    for (let j = 0; j < measurableEntities.length; j++) {
275→        if (!usedEntityIndices.has(j)) {
276→            const e = measurableEntities[j];
277→            const code = e.snomed_code ?? e.umls_cui ?? undefined;
278→            const system = e.snomed_code ? 'snomed' : e.umls_cui ? 'umls' : undefined;
279→            mappings.push({
280→                entity: entityLabel(e),
281→                entity_code: code,
282→                entity_system: system,
283→                relation: '',
284→                value: { type: 'standard', value: '', unit: '' },
285→            });
286→        }
287→    }
288→
289→    const unmatchedEntities = entities.filter(
290→        (e) =>
291→            e.entity_type === 'Condition' ||
292→            e.entity_type === 'Medication' ||
293→            e.entity_type === 'Procedure'
294→    );
295→    for (const e of unmatchedEntities) {
296→        const code = e.snomed_code ?? e.umls_cui ?? undefined;
297→        const system = e.snomed_code ? 'snomed' : e.umls_cui ? 'umls' : undefined;
298→        mappings.push({
299→            entity: entityLabel(e),
300→            entity_code: code,
301→            entity_system: system,
302→            relation: '',
303→            value: { type: 'standard', value: '', unit: '' },
304→        });
305→    }
306→
307→    if (criterion.temporal_constraint) {
308→        const tc = criterion.temporal_constraint;
309→        const duration = tc.duration as string | undefined;
310→        const referencePoint = tc.reference_point as string | undefined;
311→
312→        if (duration) {
313→            const parsed = parseDuration(duration);
314→            mappings.push({
315→                entity: referencePoint ?? '',
316→                relation: 'not_in_last' as RelationOperator,
317→                value: { type: 'temporal', duration: parsed.value, unit: parsed.unit },
318→            });
319→        }
320→    }
321→
322→    if (mappings.length === 0) return DEFAULT_FIELD_VALUES;
323→    return { mappings };
324→}
325→

 1→// TypeScript types for structured editor form
 2→
 3→export type RelationOperator =
 4→    | '='
 5→    | '!='
 6→    | '>'
 7→    | '>='
 8→    | '<'
 9→    | '<='
10→    | 'within'
11→    | 'not_in_last'
12→    | 'contains'
13→    | 'not_contains';
14→
15→export type RelationCategory = 'standard' | 'range' | 'temporal';
16→
17→export type TemporalUnit = 'days' | 'weeks' | 'months' | 'years';
18→
19→export interface StandardValue {
20→    type: 'standard';
21→    value: string;
22→    unit: string;
23→}
24→
25→export interface RangeValue {
26→    type: 'range';
27→    min: string;
28→    max: string;
29→    unit: string;
30→}
31→
32→export interface TemporalValue {
33→    type: 'temporal';
34→    duration: string;
35→    unit: TemporalUnit;
36→}
37→
38→export type FieldValue = StandardValue | RangeValue | TemporalValue;
39→
40→// Single field mapping with all possible fields
41→export interface FieldMapping {
42→    entity: string;
43→    entity_code?: string;
44→    entity_system?: string;
45→    omop_concept_id?: string;
46→    relation: RelationOperator | '';
47→    value: FieldValue;
48→}
49→
50→// Form values now contain an array of mappings
51→export interface StructuredFieldFormValues {
52→    mappings: FieldMapping[];
53→}
54→
55→export interface StructuredFieldEditorProps {
56→    criterionId: string;
57→    initialValues?: Partial<StructuredFieldFormValues>;
58→    onSave: (values: StructuredFieldFormValues) => void;
59→    onCancel: () => void;
60→    isSubmitting?: boolean;
61→}
