interface FilterBarProps {
	criteriaType: string;
	setCriteriaType: (v: string) => void;
	category: string;
	setCategory: (v: string) => void;
	minConfidence: string;
	setMinConfidence: (v: string) => void;
}

const CRITERIA_TYPES = ['inclusion', 'exclusion'];
const CATEGORIES = ['medical_history', 'lab_values', 'medications', 'procedures', 'demographics', 'other'];

export function FilterBar({
	criteriaType,
	setCriteriaType,
	category,
	setCategory,
	minConfidence,
	setMinConfidence,
}: FilterBarProps) {
	return (
		<div className="flex flex-wrap items-center gap-3">
			<select
				value={criteriaType}
				onChange={(e) => setCriteriaType(e.target.value)}
				className="rounded-md border border-input bg-background px-3 py-1.5 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring"
			>
				<option value="">All types</option>
				{CRITERIA_TYPES.map((t) => (
					<option key={t} value={t}>
						{t.charAt(0).toUpperCase() + t.slice(1)}
					</option>
				))}
			</select>

			<select
				value={category}
				onChange={(e) => setCategory(e.target.value)}
				className="rounded-md border border-input bg-background px-3 py-1.5 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring"
			>
				<option value="">All categories</option>
				{CATEGORIES.map((c) => (
					<option key={c} value={c}>
						{c.replace(/_/g, ' ')}
					</option>
				))}
			</select>

			<div className="flex items-center gap-1.5">
				<label htmlFor="min-confidence" className="text-xs text-muted-foreground">
					Min confidence:
				</label>
				<input
					id="min-confidence"
					type="number"
					min="0"
					max="1"
					step="0.1"
					value={minConfidence}
					onChange={(e) => setMinConfidence(e.target.value)}
					className="w-16 rounded-md border border-input bg-background px-2 py-1.5 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring"
					placeholder="0.0"
				/>
			</div>

			{/* Active filter chips */}
			<div className="flex flex-wrap gap-1.5">
				{criteriaType && (
					<FilterChip label="Type" value={criteriaType} onRemove={() => setCriteriaType('')} />
				)}
				{category && (
					<FilterChip
						label="Category"
						value={category.replace(/_/g, ' ')}
						onRemove={() => setCategory('')}
					/>
				)}
				{minConfidence && (
					<FilterChip
						label="Min conf"
						value={minConfidence}
						onRemove={() => setMinConfidence('')}
					/>
				)}
			</div>
		</div>
	);
}

