                            </Button>
                        </div>
                    </div>
                </header>
            )}

            <Routes>
                <Route path="/login" element={<LoginPage />} />
                <Route
                    path="/"
                    element={
                        <RequireAuth>
                            <Dashboard />
                        </RequireAuth>
                    }
                />
                <Route
                    path="/protocols"
                    element={
                        <RequireAuth>
                            <ProtocolList />
                        </RequireAuth>
                    }
                />
                <Route
                    path="/protocols/:id"
                    element={
                        <RequireAuth>
                            <ProtocolDetail />
                        </RequireAuth>
                    }
                />
                <Route
                    path="/reviews"
                    element={
                        <RequireAuth>
                            <ReviewQueue />
                        </RequireAuth>
                    }
                />
                <Route
                    path="/reviews/:batchId"
                    element={
                        <RequireAuth>
                            <ReviewPage />
                        </RequireAuth>
                    }
